(3100, 'troubleshoot', '/ˈtrʌblʃuːt/', 'verb', '{"zh-TW":["排除故障；解決問題"],"en":["to identify and solve problems"]}', NULL, 'troubleshoot issues / troubleshoot a system / troubleshooting guide', '[{"en":"The IT team is troubleshooting the network issue.","zh-TW":"IT團隊正在排除網路故障。"},{"en":"Please refer to the troubleshooting guide.","zh-TW":"請參閱故障排除指南。"}]', '{"noun":"troubleshooting, troubleshooter","verb":"troubleshoot"}', NULL, 4, 3100, NULL),
(3101, 'trust', '/trʌst/', 'noun, verb', '{"zh-TW":["信任；信託","信任；相信"],"en":["firm belief in reliability","to believe in the honesty of"]}', NULL, 'build trust / trust fund / mutual trust', '[{"en":"Building trust with customers takes time.","zh-TW":"與客戶建立信任需要時間。"},{"en":"We trust our suppliers to deliver on time.","zh-TW":"我們相信供應商會準時交貨。"}]', '{"noun":"trust, trustee","verb":"trust","adjective":"trustworthy, trusted"}', NULL, 2, 3101, NULL),
(3102, 'try', 'traɪ', 'verb', '{"zh-TW":["嘗試；努力","審判"],"en":["to make an effort to do","to test"]}', NULL, 'try a new approach', '[{"en":"Please try to complete the task today.","zh-TW":"請嘗試今天完成任務。"}]', '{"noun":"try, trial","adjective":"trying"}', NULL, 1, 3102, NULL),
(3103, 'tsunami', '/tsuːˈnɑːmi/', 'noun', '{"zh-TW":["海嘯"],"en":["a very large ocean wave caused by an earthquake"]}', '{"root":{"text":"tsu-nami","meaning":"harbor wave (港灣的波浪)"},"logic":"源自日語「津波」（港灣的波浪）。"}', 'tsunami warning / trigger a tsunami', '[{"en":"The earthquake triggered a massive tsunami.","zh-TW":"地震引發了一場巨大的海嘯。"},{"en":"Coastal residents were evacuated after the tsunami warning.","zh-TW":"海嘯警報後沿海居民被疏散。"}]', NULL, NULL, 3, 3103, NULL),
(3104, 'tuition', '/tjuːˈɪʃən/', 'noun', '{"zh-TW":["學費；教學","學費"],"en":["money paid for instruction","teaching","the money paid for being taught"]}', NULL, 'tuition fee / tuition reimbursement; tuition fee / tuition waiver', '[{"en":"The company offers tuition reimbursement.","zh-TW":"公司提供學費補助。"},{"en":"Tuition fees have increased by 5%.","zh-TW":"學費上漲了5%。"},{"en":"Tuition costs keep rising.","zh-TW":"學費持續上漲。"},{"en":"She received a tuition waiver.","zh-TW":"她獲得了學費減免。"}]', '{"noun":"tuition"}', NULL, 3, 3104, NULL),
(3105, 'turboprop', '/ˈtɜːrbəʊprɒp/', 'noun', '{"zh-TW":["渦輪螺旋槳飛機"],"en":["an aircraft powered by turbine engines driving propellers"]}', NULL, 'turboprop aircraft / turboprop service', '[{"en":"The regional route is served by a turboprop aircraft.","zh-TW":"該地區航線由渦輪螺旋槳飛機提供服務。"},{"en":"Turboprop planes are common on short regional routes.","zh-TW":"渦輪螺旋槳飛機常見於短程地區航線。"}]', NULL, NULL, 3, 3105, NULL),
(3106, 'turbulence', '/ˈtɜːrbjʊləns/', 'noun', '{"zh-TW":["亂流；湍流"],"en":["irregular air movement causing an aircraft to shake"]}', NULL, 'encounter turbulence / severe turbulence', '[{"en":"The flight encountered turbulence over the mountains.","zh-TW":"飛機在山區遭遇亂流。"},{"en":"Fasten your seatbelt in case of turbulence.","zh-TW":"繫好安全帶以防亂流。"}]', '{"adjective":"turbulent"}', NULL, 4, 3106, NULL),
(3107, 'turn', 'tɜːrn', 'verb', '{"zh-TW":["轉向；變成","輪到"],"en":["to change direction","to become"]}', NULL, 'turn down/around', '[{"en":"The company turned a profit last year.","zh-TW":"公司去年實現了盈利。"}]', '{"noun":"turn","adjective":"turning"}', NULL, 1, 3107, NULL),
(3108, 'turnaround', '/ˈtɜːrnaraʊnd/', 'noun', '{"zh-TW":["轉機；扭虧為盈"],"en":["a recovery from a difficult financial or operational situation"]}', NULL, 'business turnaround / corporate turnaround / turnaround plan / turnaround strategy', '[{"en":"The new CEO engineered a remarkable turnaround in two years.","zh-TW":"新執行長在兩年內創造了顯著的扭虧為盈。"},{"en":"The turnaround plan included cost cuts, new products, and leadership changes.","zh-TW":"轉機計劃包括成本削減、新產品和領導層變更。"}]', '{"verb":"turn around","adjective":"turnaround"}', NULL, 4, 3108, 944),
(3109, 'turnkey', '/ˈtɜːrnkiː/', 'adjective', '{"zh-TW":["交鑰匙的；即可使用的"],"en":["ready for immediate use after purchase or installation"]}', NULL, 'turnkey solution / turnkey project', '[{"en":"The company offered a turnkey solution for the factory setup.","zh-TW":"公司為工廠設置提供了交鑰匙解決方案。"},{"en":"A turnkey project is delivered ready for the client to operate.","zh-TW":"交鑰匙項目交付時即可供客戶運營。"}]', NULL, NULL, 3, 3109, NULL),
(3110, 'turnout', '/ˈtɜːrnaʊt/', 'noun', '{"zh-TW":["出席人數；參與率"],"en":["the number of people attending an event"]}', NULL, 'high turnout / voter turnout / expected turnout', '[{"en":"The conference had a higher turnout than expected.","zh-TW":"會議的出席人數超出預期。"},{"en":"Voter turnout was at an all-time high.","zh-TW":"投票率創下歷史新高。"}]', '{"noun":"turnout"}', NULL, 3, 3110, NULL),
(3111, 'turnover', '/ˈtɜːrnoʊvər/', 'noun', '{"zh-TW":["營業額；員工流動率"],"en":["the amount of business done; the rate of employee replacement"]}', NULL, 'staff turnover / annual turnover / high turnover', '[{"en":"The annual turnover reached $10 million.","zh-TW":"年營業額達到一千萬美元。"},{"en":"High staff turnover increases recruitment costs.","zh-TW":"高員工流動率增加了招募成本。"}]', '{"noun":"turnover"}', NULL, 3, 3111, 472),
(3112, 'turnround', '/ˈtɜːrnəraʊnd/', 'noun', '{"zh-TW":["週轉時間；好轉"],"en":["the time needed to complete a process; a recovery"]}', NULL, 'quick turnaround / turnaround time / business turnaround', '[{"en":"The turnaround time for orders is 48 hours.","zh-TW":"訂單的週轉時間為48小時。"},{"en":"The new CEO achieved a remarkable business turnaround.","zh-TW":"新任執行長實現了顯著的業務好轉。"}]', '{"noun":"turnaround"}', NULL, 3, 3112, NULL),
(3113, 'tutor', '/ˈtjuːtər/', 'noun', '{"zh-TW":["家教；導師","輔導"],"en":["a private teacher","to teach individually"]}', NULL, 'private tutor / math tutor; private tutor / tutor sessions / peer tutor', '[{"en":"She hired a math tutor.","zh-TW":"她請了一位數學家教。"},{"en":"The tutor helped him pass the exam.","zh-TW":"家教幫他通過了考試。"},{"en":"She hired a tutor to improve her English.","zh-TW":"她聘請了一位家教來提升英文。"},{"en":"Senior staff tutor new employees during onboarding.","zh-TW":"資深員工在入職期間輔導新員工。"}]', '{"verb":"tutor","noun2":"tutoring","noun":"tutor, tutorial, tutoring"}', NULL, 2, 3113, NULL),
(3114, 'type', 'taɪp', 'noun', '{"zh-TW":["類型；種類","字體"],"en":["a category or kind","printed characters"]}', NULL, 'type of/different types', '[{"en":"What type of service do you offer?","zh-TW":"您提供哪種類型的服務？"}]', '{"verb":"type","adjective":"typical","adverb":"typically"}', NULL, 1, 3114, NULL),
(3115, 'typhoon', '/taɪˈfuːn/', 'noun', '{"zh-TW":["颱風"],"en":["a tropical storm in the western Pacific"]}', '{"root":{"text":"typhoon","meaning":"great wind (大風)"},"logic":"源自中文「大風」或阿拉伯語 tufan。"}', 'typhoon season / typhoon warning', '[{"en":"The typhoon brought heavy rain and strong winds.","zh-TW":"颱風帶來暴雨和強風。"},{"en":"All flights were cancelled due to the typhoon.","zh-TW":"所有航班因颱風取消。"}]', NULL, NULL, 3, 3115, NULL),
(3116, 'typical', '/ˈtɪpɪkl/', 'adjective', '{"zh-TW":["典型的；代表性的"],"en":["having the distinctive qualities of a type"]}', NULL, 'typical example / typical day / typical customer', '[{"en":"A typical workday starts at 9 AM.","zh-TW":"典型的工作日從上午9點開始。"},{"en":"This is a typical example of market fluctuation.","zh-TW":"這是市場波動的典型例子。"}]', '{"adjective":"typical","adverb":"typically"}', NULL, 3, 3116, NULL),
(3117, 'ultimate', '/ˈʌltɪmət/', 'adjective', '{"zh-TW":["最終的；終極的"],"en":["being the final or fundamental"]}', NULL, 'ultimate goal / ultimate decision / ultimate responsibility', '[{"en":"Our ultimate goal is customer satisfaction.","zh-TW":"我們的最終目標是客戶滿意。"},{"en":"The CEO has ultimate responsibility for the decision.","zh-TW":"執行長對這個決定承擔最終責任。"}]', '{"adjective":"ultimate","adverb":"ultimately","noun":"ultimatum"}', NULL, 3, 3117, NULL),
(3118, 'ultrasound', '/ˈʌltrəˌsaʊnd/', 'noun', '{"zh-TW":["超音波"],"en":["an imaging technique using high-frequency sound waves"]}', NULL, 'ultrasound scan / abdominal ultrasound', '[{"en":"The ultrasound confirmed the pregnancy at eight weeks.","zh-TW":"超音波確認了八週的懷孕情況。"},{"en":"An abdominal ultrasound checks organs such as the liver.","zh-TW":"腹部超音波檢查肝臟等器官。"}]', NULL, NULL, 4, 3118, NULL),
(3119, 'unanimous', '/juːˈnænɪməs/', 'adjective', '{"zh-TW":["一致的；無異議的"],"en":["fully in agreement"]}', NULL, 'unanimous decision / unanimous vote / unanimous support', '[{"en":"The board made a unanimous decision to proceed.","zh-TW":"董事會一致決定繼續進行。"},{"en":"The proposal received unanimous support.","zh-TW":"該提案獲得了一致支持。"}]', '{"noun":"unanimity","adjective":"unanimous","adverb":"unanimously"}', NULL, 3, 3119, NULL),
(3120, 'undercut', '/ˌʌndərˈkʌt/', 'verb', '{"zh-TW":["削價競爭；壓低價格"],"en":["to price goods or services lower than competitors to gain business"]}', NULL, 'undercut the competition / undercut on price', '[{"en":"The new supplier undercut established players by 20% to win the contract.","zh-TW":"新供應商以低20%的價格削價競爭以贏得合約。"},{"en":"Undercutting may win short-term business but risks unsustainable margins.","zh-TW":"削價競爭可能贏得短期業務，但有利潤不可持續的風險。"}]', '{"noun":"undercutting"}', NULL, 3, 3120, NULL),
(3121, 'underestimate', '/ˌʌndərˈestɪmeɪt/', 'verb', '{"zh-TW":["低估"],"en":["to estimate as less than the actual value"]}', NULL, 'underestimate the cost / underestimate the risk / never underestimate', '[{"en":"Never underestimate the importance of customer feedback.","zh-TW":"永遠不要低估客戶回饋的重要性。"},{"en":"We underestimated the project timeline.","zh-TW":"我們低估了專案的時程。"}]', '{"noun":"underestimation","verb":"underestimate"}', NULL, 5, 3121, NULL),
(3122, 'undergo', '/ˌʌndərˈɡoʊ/', 'verb', '{"zh-TW":["經歷；接受"],"en":["to experience or be subjected to"]}', NULL, 'undergo changes / undergo training / undergo surgery', '[{"en":"The company is undergoing major restructuring.","zh-TW":"公司正在經歷重大重組。"},{"en":"All employees must undergo safety training.","zh-TW":"所有員工都必須接受安全訓練。"}]', '{"verb":"undergo"}', NULL, 3, 3122, NULL),
(3123, 'undergraduate', '/ˌʌndərˈɡrædʒuɪt/', 'noun', '{"zh-TW":["大學生；本科生","大學生"],"en":["a university student who has not yet received a first degree","a student studying for a first degree"]}', NULL, 'undergraduate degree / undergraduate program; undergraduate program / undergraduate student', '[{"en":"She completed her undergraduate degree in economics.","zh-TW":"她完成了經濟學的學士學位。"},{"en":"We recruit from top undergraduate programs.","zh-TW":"我們從頂尖大學課程招聘。"},{"en":"She''s an undergraduate at Oxford.","zh-TW":"她是牛津大學的大學生。"},{"en":"The undergraduate program lasts four years.","zh-TW":"大學學程為期四年。"}]', '{"noun":"undergraduate","adjective":"undergraduate"}', NULL, 5, 3123, NULL),
(3124, 'underline', '/ˌʌndərˈlaɪn/', 'verb', '{"zh-TW":["強調；突顯"],"en":["to emphasize; to draw attention to"]}', NULL, 'underline the importance / underline the need', '[{"en":"The report underlines the need for investment.","zh-TW":"報告強調了投資的必要性。"},{"en":"Recent events underline the importance of planning.","zh-TW":"近期事件突顯了規劃的重要性。"}]', '{"verb":"underline"}', NULL, 3, 3124, NULL),
(3125, 'undermine', '/ˌʌndərˈmaɪn/', 'verb', '{"zh-TW":["破壞；削弱"],"en":["to weaken or damage gradually"]}', NULL, 'undermine confidence / undermine authority / undermine efforts', '[{"en":"The scandal undermined public confidence.","zh-TW":"醜聞破壞了公眾信心。"},{"en":"Internal conflicts undermine team productivity.","zh-TW":"內部衝突削弱了團隊生產力。"}]', '{"verb":"undermine"}', NULL, 3, 3125, NULL),
(3126, 'underperform', '/ˌʌndərpəˈfɔːrm/', 'verb', '{"zh-TW":["表現不佳；低於預期"],"en":["to perform less well than expected or required"]}', NULL, 'underperform expectations / underperform the market', '[{"en":"The division underperformed its targets for the third consecutive quarter.","zh-TW":"該部門連續第三個季度未能達到目標。"},{"en":"The stock continued to underperform the market index.","zh-TW":"該股票繼續低於市場指數的表現。"}]', '{"noun":"underperformance","adjective":"underperforming"}', NULL, 4, 3126, NULL),
(3127, 'underperformance', '/ˌʌndərpəˈfɔːrməns/', 'noun', '{"zh-TW":["績效不佳；表現欠佳"],"en":["the failure to achieve expected standards of performance"]}', NULL, 'address underperformance / underperformance of a fund', '[{"en":"The fund''s underperformance relative to the index prompted a management review.","zh-TW":"基金相對於指數的績效不佳促使了管理層審查。"},{"en":"A performance improvement plan is triggered when underperformance is identified.","zh-TW":"當識別到績效不佳時，績效改進計劃被觸發。"}]', '{"verb":"underperform"}', NULL, 5, 3127, NULL),
(3128, 'underprice', '/ˌʌndərˈpraɪs/', 'verb', '{"zh-TW":["低估定價；定價過低"],"en":["to set a price for a product or service below its true value"]}', NULL, 'underprice a product / risk of underpricing', '[{"en":"Underpricing the new product led to rapid adoption but thin margins.","zh-TW":"對新產品低估定價導致了迅速採用但利潤微薄。"},{"en":"Competitors underpriced the market to gain initial share.","zh-TW":"競爭對手對市場低估定價以獲取初始份額。"}]', '{"noun":"underpricing","adjective":"underpriced"}', NULL, 4, 3128, NULL),
(3129, 'understand', 'ˌʌndərˈstænd', 'verb', '{"zh-TW":["理解；明白","接受"],"en":["to know the meaning of","to accept"]}', NULL, 'understand a concept/policy', '[{"en":"I fully understand your concern.","zh-TW":"我完全理解您的擔憂。"}]', '{"noun":"understanding","adjective":"understandable","adverb":"understandably"}', NULL, 4, 3129, NULL),
(3130, 'undertake', '/ˌʌndərˈteɪk/', 'verb', '{"zh-TW":["承擔；從事"],"en":["to commit to doing something"]}', NULL, 'undertake a project / undertake research / undertake responsibility', '[{"en":"We undertook a comprehensive market study.","zh-TW":"我們進行了全面的市場研究。"},{"en":"The firm undertook the renovation project.","zh-TW":"該公司承擔了翻新工程。"}]', '{"noun":"undertaking","verb":"undertake"}', NULL, 3, 3130, NULL),
(3131, 'underway', '/ˌʌndərˈweɪ/', 'adjective, adverb', '{"zh-TW":["進行中的"],"en":["having started and in progress"]}', NULL, 'get underway / already underway / well underway', '[{"en":"Construction is already underway at the new site.","zh-TW":"新址的建設已經在進行中。"},{"en":"Plans are well underway for the expansion.","zh-TW":"擴張計畫正在順利進行中。"}]', '{"adjective":"underway"}', NULL, 3, 3131, NULL),
(3132, 'underwrite', '/ˌʌndərˈraɪt/', 'verb', '{"zh-TW":["承保；擔保"],"en":["to accept financial responsibility for","to insure"]}', NULL, 'underwrite a loan / underwrite an IPO', '[{"en":"The bank agreed to underwrite the bond issue.","zh-TW":"銀行同意承銷債券發行。"},{"en":"Insurance companies underwrite risk.","zh-TW":"保險公司承保風險。"}]', '{"verb":"underwrite","noun":"underwriter","noun2":"underwriting"}', NULL, 4, 3132, NULL),
(3133, 'underwriter', '/ˈʌndərˌraɪtər/', 'noun', '{"zh-TW":["承銷商；保險商"],"en":["a financial institution that manages the sale of new securities"]}', NULL, 'lead underwriter / underwriter agreement / insurance underwriter', '[{"en":"The bank acted as lead underwriter for the bond issuance.","zh-TW":"銀行擔任債券發行的主承銷商。"},{"en":"Underwriters priced the IPO at $20 per share.","zh-TW":"承銷商將首次公開募股定價為每股20美元。"}]', '{"verb":"underwrite","noun":"underwriting"}', NULL, 4, 3133, NULL),
(3134, 'underwriting', '/ˈʌndərˌraɪtɪŋ/', 'noun', '{"zh-TW":["承保；核保"],"en":["the process of evaluating and assuming financial risk for a fee"]}', NULL, 'insurance underwriting / mortgage underwriting / underwriting criteria', '[{"en":"Underwriting standards were tightened after the financial crisis.","zh-TW":"金融危機後，核保標準收緊了。"},{"en":"The underwriting process determines the premium rate and coverage.","zh-TW":"核保流程確定保費費率和保障範圍。"}]', '{"verb":"underwrite","noun":"underwriter"}', NULL, 4, 3134, NULL),
(3135, 'unemployment', '/ˌʌnɪmˈplɔɪmənt/', 'noun', '{"zh-TW":["失業；失業率"],"en":["the state of being without a job"]}', NULL, 'unemployment rate / unemployment benefits / reduce unemployment', '[{"en":"The unemployment rate dropped to 4%.","zh-TW":"失業率降至4%。"},{"en":"Government programs aim to reduce unemployment.","zh-TW":"政府計畫旨在降低失業率。"}]', '{"noun":"unemployment, employment","adjective":"unemployed, employed","verb":"employ"}', NULL, 4, 3135, NULL),
(3136, 'unforeseen', '/ˌʌnfɔːrˈsiːn/', 'adjective', '{"zh-TW":["無法預見的；意外的"],"en":["not anticipated or predicted"]}', NULL, 'unforeseen circumstances / unforeseen problems / unforeseen delays', '[{"en":"Unforeseen circumstances caused the project delay.","zh-TW":"不可預見的情況導致專案延遲。"},{"en":"We must prepare for unforeseen risks.","zh-TW":"我們必須為不可預見的風險做準備。"}]', '{"adjective":"unforeseen, foreseen","verb":"foresee"}', NULL, 4, 3136, NULL),
(3137, 'uniform', '/ˈjuːnɪfɔːrm/', 'adjective, noun', '{"zh-TW":["統一的；一致的","制服"],"en":["consistent; not varying","a distinctive set of clothes"]}', NULL, 'uniform standard / uniform policy / uniform across', '[{"en":"The company enforces uniform quality standards.","zh-TW":"公司執行統一的品質標準。"},{"en":"Pricing must be uniform across all regions.","zh-TW":"定價在所有地區必須一致。"}]', '{"noun":"uniform, uniformity","adjective":"uniform","adverb":"uniformly"}', NULL, 3, 3137, 473),
(3138, 'unilateral', '/ˌjuːnɪˈlætərəl/', 'adjective', '{"zh-TW":["單方面的；片面的"],"en":["decided or taken by one party without consulting others"]}', NULL, 'unilateral decision / unilateral termination', '[{"en":"The unilateral termination of the contract was challenged in court.","zh-TW":"合約的單方面終止在法庭上受到了質疑。"},{"en":"A unilateral change to the terms is not permitted without consent.","zh-TW":"未經同意不得單方面更改條款。"}]', '{"adverb":"unilaterally"}', NULL, 4, 3138, NULL),
(3139, 'unique', '/juːˈniːk/', 'adjective', '{"zh-TW":["獨特的；唯一的"],"en":["being the only one of its kind"]}', NULL, 'unique opportunity / unique selling point / unique feature', '[{"en":"Each product has a unique serial number.","zh-TW":"每個產品都有獨特的序號。"},{"en":"Our unique selling point is personalized service.","zh-TW":"我們的獨特賣點是個人化服務。"}]', '{"noun":"uniqueness","adjective":"unique","adverb":"uniquely"}', NULL, 2, 3139, 474),
(3140, 'unit', '/ˈjuːnɪt/', 'noun', '{"zh-TW":["單位；部門"],"en":["an individual thing; a section of an organization"]}', NULL, 'business unit / per unit / unit cost', '[{"en":"The cost per unit decreased with higher volume.","zh-TW":"隨著產量增加，單位成本下降。"},{"en":"The marketing unit launched a new campaign.","zh-TW":"行銷部門推出了新活動。"}]', '{"noun":"unit, unity","verb":"unite","adjective":"united"}', NULL, 1, 3140, NULL),
(3141, 'universal', '/ˌjuːnɪˈvɜːrsl/', 'adjective', '{"zh-TW":["普遍的；全球的"],"en":["relating to all people or things"]}', NULL, 'universal access / universal standard / universal appeal', '[{"en":"The policy aims for universal access to healthcare.","zh-TW":"該政策旨在實現全民醫療保健。"},{"en":"Good customer service has universal appeal.","zh-TW":"良好的客戶服務具有普遍的吸引力。"}]', '{"noun":"universality","adjective":"universal","adverb":"universally"}', NULL, 3, 3141, 945),
(3142, 'university', '/ˌjuːnɪˈvɜːrsɪti/', 'noun', '{"zh-TW":["大學"],"en":["an institution of higher learning"]}', NULL, 'go to university / university degree', '[{"en":"She graduated from a top university.","zh-TW":"她從頂尖大學畢業。"},{"en":"Which university did you attend?","zh-TW":"你讀哪所大學？"}]', NULL, NULL, 4, 3142, NULL),
(3143, 'unprecedented', '/ʌnˈpresɪdentɪd/', 'adjective', '{"zh-TW":["前所未有的；空前的"],"en":["never done or known before"]}', NULL, 'unprecedented growth / unprecedented challenge / unprecedented demand', '[{"en":"The company experienced unprecedented demand.","zh-TW":"公司經歷了前所未有的需求。"},{"en":"We face unprecedented challenges in the market.","zh-TW":"我們在市場上面臨空前的挑戰。"}]', '{"adjective":"unprecedented, precedented"}', NULL, 5, 3143, NULL),
(3144, 'unveil', '/ʌnˈveɪl/', 'verb', '{"zh-TW":["揭露；公布"],"en":["to show or reveal something new"]}', NULL, 'unveil a plan / unveil a product / unveil a strategy', '[{"en":"The CEO unveiled the new product line at the conference.","zh-TW":"執行長在會議上公布了新產品線。"},{"en":"The government unveiled its economic recovery plan.","zh-TW":"政府公布了經濟復甦計畫。"}]', '{"verb":"unveil","noun":"unveiling"}', NULL, 2, 3144, NULL),
(3145, 'unwind', '/ʌnˈwaɪnd/', 'verb', '{"zh-TW":["平倉；解除"],"en":["to reverse or close out a financial position or transaction"]}', NULL, 'unwind a position / unwind a trade', '[{"en":"The hedge fund began to unwind its leveraged positions.","zh-TW":"對沖基金開始平倉其槓桿倉位。"},{"en":"The transaction was unwound after the deal fell through.","zh-TW":"交易在失敗後被解除了。"}]', '{"noun":"unwinding","adjective":"unwound"}', NULL, 2, 3145, NULL),
(3146, 'up-to-date', 'ʌp tə ˈdeɪt', 'adjective', '{"zh-TW":["最新的；及時更新的","符合現代的"],"en":["incorporating latest information","current"]}', NULL, 'up-to-date report/up-to-date records', '[{"en":"Please keep your records up to date.","zh-TW":"請保持記錄最新。"}]', '{"adverb":"up to date"}', NULL, 4, 3146, NULL),
(3147, 'upcycling', '/ˈʌpsaɪklɪŋ/', 'noun', '{"zh-TW":["升級再造；升級回收"],"en":["converting waste into something of higher value"]}', NULL, 'upcycling project / practice upcycling', '[{"en":"Upcycling old furniture reduces waste and saves money.","zh-TW":"升級再造舊家具可減少浪費並節省費用。"},{"en":"The brand is known for upcycling discarded materials into fashionable products.","zh-TW":"該品牌以將廢棄材料升級再造成時尚產品而聞名。"}]', '{"verb":"upcycle"}', NULL, 3, 3147, NULL),
(3148, 'update', '/ʌpˈdeɪt/', 'noun, verb', '{"zh-TW":["更新；最新資訊","更新"],"en":["new information; a newer version","to bring up to date"]}', NULL, 'software update / provide an update / update regularly', '[{"en":"Please update the spreadsheet with the latest data.","zh-TW":"請用最新數據更新試算表。"},{"en":"I''ll provide a weekly status update.","zh-TW":"我會提供每週的進度更新。"}]', '{"noun":"update","verb":"update"}', NULL, 2, 3148, 235),
(3149, 'upgrade', '/ʌpˈɡreɪd/', 'noun, verb', '{"zh-TW":["升級","升級"],"en":["an improvement; a higher version","to raise to a higher standard"]}', NULL, 'system upgrade / upgrade to / free upgrade', '[{"en":"We upgraded our servers last month.","zh-TW":"上個月我們升級了伺服器。"},{"en":"Customers can upgrade to the premium plan.","zh-TW":"客戶可以升級到高級方案。"}]', '{"noun":"upgrade","verb":"upgrade"}', NULL, 3, 3149, NULL);
