(3156, 'upskill', '/ˌʌpˈskɪl/', 'verb', '{"zh-TW":["提升技能；再培訓"],"en":["to learn new skills or teach workers new skills to improve competence"]}', NULL, 'upskill employees / upskill the workforce', '[{"en":"The company invested in upskilling employees in digital tools.","zh-TW":"公司投資於提升員工在數位工具方面的技能。"},{"en":"Upskilling reduces the need for external hiring.","zh-TW":"提升技能減少了對外部招聘的需求。"}]', '{"noun":"upskilling"}', NULL, 3, 3156, NULL),
(3157, 'upstream', '/ˈʌpstriːm/', 'adjective', '{"zh-TW":["上游的"],"en":["relating to the early stages of production or supply chain activities"]}', NULL, 'upstream supplier / upstream process / upstream operations', '[{"en":"Upstream operations include raw material sourcing and primary processing.","zh-TW":"上游運營包括原材料採購和初級加工。"},{"en":"A disruption at an upstream supplier can halt the entire production line.","zh-TW":"上游供應商的中斷可能導致整條生產線停工。"}]', '{"opposite":"downstream"}', NULL, 3, 3157, NULL),
(3158, 'upsurge', '/ˈʌpsɜːrdʒ/', 'noun', '{"zh-TW":["激增；猛漲"],"en":["a sudden large increase in something"]}', NULL, 'upsurge in demand / upsurge in sales', '[{"en":"An upsurge in online shopping boosted warehouse capacity needs.","zh-TW":"線上購物的激增提高了對倉庫容量的需求。"},{"en":"The upsurge in raw material costs squeezed profit margins.","zh-TW":"原材料成本的猛漲壓縮了利潤率。"}]', '{"verb":"upsurge"}', NULL, 3, 3158, NULL),
