(3160, 'urban', '/ˈɜːrbən/', 'adjective', '{"zh-TW":["都市的；城市的"],"en":["relating to a city or town"]}', NULL, 'urban area / urban development / urban planning', '[{"en":"Urban areas face unique transportation challenges.","zh-TW":"都市地區面臨獨特的交通挑戰。"},{"en":"The company focuses on urban development projects.","zh-TW":"公司專注於都市開發案。"}]', '{"noun":"urbanization","adjective":"urban","verb":"urbanize"}', NULL, 2, 3160, NULL),
(3161, 'urge', '/ɜːrdʒ/', 'verb, noun', '{"zh-TW":["敦促；催促","衝動"],"en":["to strongly encourage","a strong desire"]}', NULL, 'urge caution / strongly urge / urge someone to', '[{"en":"The board urged management to cut costs.","zh-TW":"董事會敦促管理層削減成本。"},{"en":"Experts urge companies to adopt sustainable practices.","zh-TW":"專家敦促企業採用永續做法。"}]', '{"noun":"urge, urgency","verb":"urge","adjective":"urgent"}', NULL, 1, 3161, NULL),
