(3171, 'vaccine', '/ˈvæksiːn/', 'noun', '{"zh-TW":["疫苗"],"en":["a substance used to stimulate immunity to a disease"]}', NULL, 'flu vaccine / receive a vaccine', '[{"en":"The flu vaccine is recommended every autumn.","zh-TW":"建議每年秋天接種流感疫苗。"},{"en":"The vaccine has been approved for use in adults.","zh-TW":"該疫苗已獲准用於成人。"}]', '{"verb":"vaccinate","noun":"vaccination"}', NULL, 3, 3171, NULL),
