(3177, 'value', '/ˈvæljuː/', 'noun, verb', '{"zh-TW":["價值；價格","重視；估價"],"en":["the importance or worth of something","to consider important"]}', NULL, 'added value / core values / market value', '[{"en":"The company''s core values include integrity and innovation.","zh-TW":"公司的核心價值包括誠信和創新。"},{"en":"We value our employees'' contributions.","zh-TW":"我們重視員工的貢獻。"}]', '{"noun":"value, valuation","verb":"value","adjective":"valuable"}', NULL, 2, 3177, 237),
