(3183, 'vary', '/ˈveəri/', 'verb', '{"zh-TW":["變化；不同"],"en":["to differ or change","to differ; to change"]}', '{"root":{"text":"var","meaning":"change (改變)"},"suffix":{"text":"-y","meaning":"action (動作)"},"logic":"產生改變，即「變化」。"}', 'vary from / vary widely / results may vary; vary from / vary depending on / prices vary', '[{"en":"Prices vary depending on the season.","zh-TW":"價格因季節而異。"},{"en":"Opinions on this topic vary widely.","zh-TW":"對這個話題的看法差異很大。"},{"en":"Quality can vary significantly between suppliers.","zh-TW":"不同供應商之間品質差異很大。"}]', '{"noun":"variety","noun2":"variation","adjective":"various","verb":"vary"}', NULL, 1, 3183, NULL),
