(3186, 'vegan', '/ˈviːɡən/', 'adjective', '{"zh-TW":["純素的"],"en":["containing no animal products"]}', NULL, 'vegan menu / vegan option', '[{"en":"The restaurant now offers an extensive vegan menu.","zh-TW":"餐廳現在提供豐富的純素菜單。"},{"en":"Ask the chef for vegan alternatives to the main dishes.","zh-TW":"請詢問廚師主菜的純素替代選項。"}]', '{"noun":"vegan","noun2":"veganism"}', NULL, 2, 3186, NULL),
(3187, 'vegetable', '/ˈvɛdʒtəbəl/', 'noun', '{"zh-TW":["蔬菜"],"en":["a plant or part of a plant eaten as food"]}', NULL, 'fresh vegetable / seasonal vegetable', '[{"en":"The menu highlights seasonal vegetables from local farms.","zh-TW":"菜單強調來自當地農場的季節性蔬菜。"},{"en":"Add more vegetables to your diet for better health.","zh-TW":"多吃蔬菜有益健康。"}]', '{"adjective":"vegetable"}', NULL, 3, 3187, NULL),
(3188, 'vegetarian', '/ˌvɛdʒɪˈtɛəriən/', 'adjective', '{"zh-TW":["素食的"],"en":["not containing meat or fish"]}', NULL, 'vegetarian dish / vegetarian option', '[{"en":"We need a vegetarian option for one of our guests.","zh-TW":"我們需要為其中一位客人提供素食選項。"},{"en":"The restaurant has a dedicated vegetarian menu.","zh-TW":"餐廳有專門的素食菜單。"}]', '{"noun":"vegetarian","noun2":"vegetarianism"}', NULL, 4, 3188, NULL),
(3189, 'vehicle', '/ˈviːɪkl/', 'noun', '{"zh-TW":["車輛；交通工具","媒介；手段"],"en":["a means of transport","a means of expressing ideas"]}', NULL, 'electric vehicle / company vehicle / investment vehicle', '[{"en":"Electric vehicles are gaining market share.","zh-TW":"電動車正在獲得市場佔有率。"},{"en":"The newsletter is a vehicle for company announcements.","zh-TW":"電子報是公司公告的媒介。"}]', '{"noun":"vehicle","adjective":"vehicular"}', NULL, 3, 3189, NULL),
(3190, 'velocity', '/vɪˈlɒsɪti/', 'noun', '{"zh-TW":["速度；開發速率"],"en":["in agile, the amount of work a team can complete in a sprint"]}', NULL, 'team velocity / measure velocity / average velocity / increase velocity', '[{"en":"The team''s velocity increased after removing process bottlenecks.","zh-TW":"消除流程瓶頸後，團隊的開發速率提高了。"},{"en":"Velocity is measured in story points completed per sprint.","zh-TW":"速度以每個衝刺完成的故事點數衡量。"}]', '{"plural":"velocities"}', NULL, 3, 3190, NULL),
(3191, 'vendor', '/ˈvendər/', 'noun', '{"zh-TW":["供應商；賣方"],"en":["a person or company that sells goods"]}', NULL, 'vendor management / preferred vendor / third-party vendor', '[{"en":"We are evaluating new vendors for the contract.","zh-TW":"我們正在評估新的供應商。"},{"en":"The vendor delivered the goods on time.","zh-TW":"供應商準時交付了貨物。"}]', '{"noun":"vendor"}', NULL, 2, 3191, 239),
(3192, 'venture', '/ˈventʃər/', 'noun, verb', '{"zh-TW":["企業；冒險事業","冒險；敢於"],"en":["a risky business enterprise","to dare to do something risky"]}', NULL, 'joint venture / venture capital / new venture', '[{"en":"They launched a joint venture with a local partner.","zh-TW":"他們與當地合作夥伴成立了合資企業。"},{"en":"Venture capital funded the startup''s growth.","zh-TW":"風險投資資助了新創公司的成長。"}]', '{"noun":"venture, venturer","verb":"venture"}', NULL, 3, 3192, 726),
(3193, 'venue', '/ˈvɛnjuː/', 'noun', '{"zh-TW":["場地；地點"],"en":["the place where an event happens","a place where an event is held"]}', NULL, 'concert venue / change of venue; event venue / conference venue / change of venue', '[{"en":"The wedding venue is beautiful.","zh-TW":"婚禮場地很漂亮。"},{"en":"What''s the venue for the conference?","zh-TW":"會議的場地在哪裡？"},{"en":"The conference venue holds 500 attendees.","zh-TW":"會議場地可容納500位出席者。"},{"en":"We need to book a venue for the annual gala.","zh-TW":"我們需要為年度晚宴預訂場地。"}]', '{"noun":"venue"}', NULL, 2, 3193, NULL),
(3194, 'verbatim', '/vɜːrˈbeɪtɪm/', 'adverb', '{"zh-TW":["逐字地；原文照錄"],"en":["in exactly the same words as were used originally"]}', NULL, 'verbatim record / transcribe verbatim / verbatim quote', '[{"en":"The secretary recorded the CEO''s statement verbatim.","zh-TW":"秘書逐字記錄了執行長的聲明。"},{"en":"The contract was copied verbatim into the proposal document.","zh-TW":"合約被原文照錄到提案文件中。"}]', '{"adjective":"verbatim"}', NULL, 3, 3194, NULL),
(3195, 'verdict', '/ˈvɜːrdɪkt/', 'noun', '{"zh-TW":["裁決；判決"],"en":["the decision made by a jury"]}', NULL, 'guilty verdict / reach a verdict', '[{"en":"The jury reached a verdict of not guilty.","zh-TW":"陪審團做出了無罪裁決。"},{"en":"The verdict was announced in court.","zh-TW":"裁決在法庭上宣布。"}]', NULL, NULL, 3, 3195, NULL),
(3196, 'verify', '/ˈverɪfaɪ/', 'verb', '{"zh-TW":["驗證；核實"],"en":["to confirm the truth or accuracy of"]}', '{"root":{"text":"ver","meaning":"true (真實)"},"suffix":{"text":"-ify","meaning":"使..."}}', 'verify information / verify identity / verify data', '[{"en":"Please verify the information before submitting.","zh-TW":"提交前請驗證資訊。"},{"en":"We need to verify the customer''s identity.","zh-TW":"我們需要核實客戶的身分。"}]', '{"noun":"verification","verb":"verify","adjective":"verifiable"}', NULL, 2, 3196, 67),
(3197, 'versatile', '/ˈvɜːrsətl/', 'adjective', '{"zh-TW":["多功能的；多才多藝的"],"en":["able to adapt to many functions"]}', NULL, 'versatile tool / versatile employee / highly versatile', '[{"en":"The software is versatile enough for various tasks.","zh-TW":"這個軟體功能多樣，適用於各種任務。"},{"en":"She is a versatile team member.","zh-TW":"她是一位多才多藝的團隊成員。"}]', '{"noun":"versatility","adjective":"versatile"}', NULL, 3, 3197, NULL),
(3198, 'version', '/ˈvɜːrʒn/', 'noun', '{"zh-TW":["版本"],"en":["a particular form of something"]}', NULL, 'latest version / updated version / previous version', '[{"en":"Download the latest version of the app.","zh-TW":"下載應用程式的最新版本。"},{"en":"This is the final version of the report.","zh-TW":"這是報告的最終版本。"}]', '{"noun":"version"}', NULL, 3, 3198, 240),
(3199, 'veto', '/ˈviːtoʊ/', 'noun, verb', '{"zh-TW":["否決權；否決","否決"],"en":["the power to reject a decision","to reject or prohibit"]}', NULL, 'exercise a veto / veto power / veto a proposal', '[{"en":"The president vetoed the proposed legislation.","zh-TW":"總統否決了擬議的法案。"},{"en":"Shareholders have veto power over major decisions.","zh-TW":"股東對重大決策擁有否決權。"}]', '{"noun":"veto","verb":"veto"}', NULL, 1, 3199, NULL);
