(3200, 'vetting', '/ˈvɛtɪŋ/', 'noun', '{"zh-TW":["審查；背景調查"],"en":["making a careful check of someone or something"]}', NULL, 'vetting process / thorough vetting', '[{"en":"All job candidates undergo a vetting process.","zh-TW":"所有求職候選人都要經過審查流程。"},{"en":"Suppliers are subject to a vetting process before approval.","zh-TW":"供應商在批准前需經過審查流程。"}]', '{"verb":"vet","adjective":"vetted"}', NULL, 3, 3200, NULL),
(3201, 'via', '/ˈvaɪə/', 'preposition', '{"zh-TW":["經由；透過"],"en":["traveling through; by means of"]}', NULL, 'via email / via telephone / via satellite', '[{"en":"Please confirm via email.","zh-TW":"請透過電子郵件確認。"},{"en":"The goods will be shipped via air freight.","zh-TW":"貨物將透過空運運送。"}]', NULL, NULL, 1, 3201, NULL),
(3202, 'viability', '/ˌvaɪəˈbɪlɪti/', 'noun', '{"zh-TW":["可行性；存活能力"],"en":["the ability of a plan, business, or idea to work or succeed"]}', NULL, 'assess viability / financial viability / commercial viability', '[{"en":"The business plan was reviewed for long-term financial viability.","zh-TW":"商業計劃的長期財務可行性進行了審查。"},{"en":"Commercial viability depends on whether the market will pay for the product.","zh-TW":"商業可行性取決於市場是否願意為該產品付費。"}]', '{"adjective":"viable","adverb":"viably"}', NULL, 3, 3202, 948),
(3203, 'viable', '/ˈvaɪəbl/', 'adjective', '{"zh-TW":["可行的；能存活的"],"en":["capable of working successfully"]}', NULL, 'commercially viable / viable option / viable alternative', '[{"en":"Is this a commercially viable product?","zh-TW":"這是一個在商業上可行的產品嗎？"},{"en":"We need to find a viable alternative.","zh-TW":"我們需要找到一個可行的替代方案。"}]', '{"noun":"viability","adjective":"viable"}', NULL, 2, 3203, NULL),
(3204, 'view', '/vjuː/', 'noun, verb', '{"zh-TW":["觀點；看法","認為；看待"],"en":["an opinion or way of thinking","to regard in a particular way"]}', NULL, 'point of view / in view of / view as', '[{"en":"In view of the circumstances, we postponed the launch.","zh-TW":"鑑於情況，我們延後了發布。"},{"en":"Management views this as a positive development.","zh-TW":"管理層視此為正面的發展。"}]', '{"noun":"view, viewer, viewpoint","verb":"view, review"}', NULL, 1, 3204, NULL),
(3205, 'violate', '/ˈvaɪəleɪt/', 'verb', '{"zh-TW":["違反；侵犯"],"en":["to break a law or agreement"]}', NULL, 'violate regulations / violate a contract / violate privacy', '[{"en":"The company violated environmental regulations.","zh-TW":"該公司違反了環境法規。"},{"en":"Sharing data without consent violates privacy laws.","zh-TW":"未經同意分享數據違反了隱私法。"}]', '{"noun":"violation","verb":"violate"}', NULL, 3, 3205, NULL),
(3206, 'virtual', '/ˈvɜːrtʃuəl/', 'adjective', '{"zh-TW":["虛擬的","虛擬的；實質上的"],"en":["created by computer; almost complete","existing in digital form; nearly as described"]}', NULL, 'virtual reality / virtual meeting; virtual meeting / virtual reality / virtual office', '[{"en":"We had a virtual meeting today.","zh-TW":"我們今天開了一場線上會議。"},{"en":"Virtual reality is becoming more popular.","zh-TW":"虛擬實境越來越受歡迎。"},{"en":"The team holds virtual meetings every Monday.","zh-TW":"團隊每週一舉行視訊會議。"},{"en":"Virtual reality is transforming training programs.","zh-TW":"虛擬實境正在改變培訓計畫。"}]', '{"adverb":"virtually","adjective":"virtual"}', NULL, 3, 3206, NULL),
(3207, 'virtualization', '/ˌvɜːrtʃuəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["虛擬化"],"en":["creating virtual versions of hardware, software, or storage resources"]}', NULL, 'server virtualization / network virtualization / virtualization technology', '[{"en":"Server virtualization reduced hardware costs significantly.","zh-TW":"伺服器虛擬化顯著降低了硬體成本。"},{"en":"Virtualization allows multiple operating systems to run on one server.","zh-TW":"虛擬化允許多個作業系統在一台伺服器上運行。"}]', '{"verb":"virtualize","adjective":"virtualized"}', NULL, 5, 3207, NULL),
(3208, 'virtue', '/ˈvɜːrtʃuː/', 'noun', '{"zh-TW":["美德；優點"],"en":["moral excellence; an advantage"]}', NULL, 'by virtue of / virtue of patience / corporate virtue', '[{"en":"By virtue of her experience, she was promoted.","zh-TW":"憑藉她的經驗，她獲得了升遷。"},{"en":"Patience is a virtue in negotiations.","zh-TW":"在談判中耐心是一種美德。"}]', '{"noun":"virtue","adjective":"virtuous"}', NULL, 2, 3208, NULL),
(3209, 'virus', '/ˈvaɪrəs/', 'noun', '{"zh-TW":["病毒；電腦病毒"],"en":["harmful code that spreads between computers"]}', NULL, 'computer virus / virus protection', '[{"en":"My computer has a virus.","zh-TW":"我的電腦中了病毒。"},{"en":"Update your virus protection software.","zh-TW":"更新你的防毒軟體。"}]', '{"adjective":"viral"}', NULL, 2, 3209, NULL),
(3210, 'visa', '/ˈviːzə/', 'noun', '{"zh-TW":["簽證"],"en":["an official endorsement on a passport allowing entry to a country"]}', NULL, 'obtain a visa / visa application', '[{"en":"You need a valid visa to enter the country.","zh-TW":"您需要有效簽證才能入境該國。"},{"en":"The visa application process can take several weeks.","zh-TW":"簽證申請過程可能需要幾個星期。"}]', NULL, NULL, 1, 3210, NULL),
(3211, 'visible', '/ˈvɪzəbl/', 'adjective', '{"zh-TW":["可見的；明顯的"],"en":["able to be seen or noticed"]}', NULL, 'clearly visible / visible results / highly visible', '[{"en":"The results of the new strategy are clearly visible.","zh-TW":"新策略的成果清晰可見。"},{"en":"The brand needs to be more visible in the market.","zh-TW":"品牌需要在市場上更加顯眼。"}]', '{"noun":"visibility","adjective":"visible, invisible","adverb":"visibly"}', NULL, 3, 3211, 480),
(3212, 'vision', '/ˈvɪʒn/', 'noun', '{"zh-TW":["願景；眼光","視力"],"en":["an idea of what the future could be","the ability to see"]}', NULL, 'company vision / long-term vision / share a vision', '[{"en":"The CEO shared her vision for the company''s future.","zh-TW":"執行長分享了她對公司未來的願景。"},{"en":"A clear vision helps align team efforts.","zh-TW":"清晰的願景有助於統一團隊的努力方向。"}]', '{"noun":"vision, visionary","adjective":"visionary"}', NULL, 2, 3212, NULL),
(3213, 'visit', 'ˈvɪzɪt', 'verb', '{"zh-TW":["拜訪；參觀","訪問"],"en":["to go to see someone or a place","to access a website"]}', NULL, 'visit a client/site', '[{"en":"The manager visited three clients this week.","zh-TW":"經理本週拜訪了三位客戶。"}]', '{"noun":"visit, visitor","adjective":"visiting"}', NULL, 2, 3213, NULL),
(3214, 'vital', '/ˈvaɪtl/', 'adjective', '{"zh-TW":["至關重要的；不可或缺的"],"en":["absolutely necessary; essential"]}', NULL, 'vital role / vital importance / vital information', '[{"en":"Communication plays a vital role in teamwork.","zh-TW":"溝通在團隊合作中扮演至關重要的角色。"},{"en":"It is vital that we meet the deadline.","zh-TW":"我們必須在截止日前完成，這至關重要。"}]', '{"adjective":"vital","adverb":"vitally","noun":"vitality"}', NULL, 2, 3214, 481),
(3215, 'void', '/vɔɪd/', 'adjective', '{"zh-TW":["無效的；無法律效力的"],"en":["having no legal force or effect"]}', NULL, 'render void / null and void / void contract', '[{"en":"A contract signed under duress may be rendered void.","zh-TW":"在脅迫下簽署的合約可能被視為無效。"},{"en":"The court declared the agreement null and void.","zh-TW":"法院宣佈協議無效。"}]', '{"verb":"void","noun":"voidance"}', NULL, 1, 3215, NULL),
(3216, 'volatile', '/ˈvɑːlətl/', 'adjective', '{"zh-TW":["波動的；不穩定的"],"en":["liable to change rapidly and unpredictably"]}', NULL, 'volatile market / volatile prices / highly volatile', '[{"en":"The stock market has been highly volatile this year.","zh-TW":"今年股市波動劇烈。"},{"en":"Oil prices remain volatile due to geopolitical tensions.","zh-TW":"由於地緣政治緊張，油價持續波動。"}]', '{"noun":"volatility","adjective":"volatile"}', NULL, 3, 3216, NULL),
(3217, 'volatility', '/ˌvɒləˈtɪlɪti/', 'noun', '{"zh-TW":["波動性；波動率"],"en":["the degree of variation in a financial instrument''s price over time"]}', NULL, 'market volatility / high volatility / volatility index / manage volatility', '[{"en":"Market volatility increased sharply during the crisis.","zh-TW":"危機期間市場波動性急劇增加。"},{"en":"Investors avoid high-volatility stocks during uncertain times.","zh-TW":"投資者在不確定時期避開高波動性股票。"}]', '{"adjective":"volatile"}', NULL, 4, 3217, NULL),
(3218, 'volcano', '/vɒlˈkeɪnoʊ/', 'noun', '{"zh-TW":["火山"],"en":["a mountain that can erupt with lava and ash"]}', '{"root":{"text":"Vulcan","meaning":"Roman god of fire (火神)"},"logic":"以羅馬火神 Vulcan 命名。"}', 'active volcano / volcanic eruption', '[{"en":"The volcano erupted without warning.","zh-TW":"火山毫無預警地噴發。"},{"en":"Hawaii has several active volcanoes.","zh-TW":"夏威夷有幾座活火山。"}]', '{"adjective":"volcanic","noun":"volcanism"}', NULL, 3, 3218, NULL),
(3219, 'volume', '/ˈvɑːljuːm/', 'noun', '{"zh-TW":["量；體積","音量；冊"],"en":["the amount or quantity","the degree of loudness"]}', NULL, 'sales volume / high volume / trading volume', '[{"en":"Sales volume increased by 25% this year.","zh-TW":"今年銷售量增加了25%。"},{"en":"High-volume production reduces unit costs.","zh-TW":"大量生產降低了單位成本。"}]', '{"noun":"volume","adjective":"voluminous"}', NULL, 2, 3219, 241),
(3220, 'voluntary', '/ˈvɑːlənteri/', 'adjective', '{"zh-TW":["自願的；志願的"],"en":["done by choice; not compulsory"]}', NULL, 'voluntary participation / voluntary redundancy / voluntary work', '[{"en":"Participation in the survey is voluntary.","zh-TW":"參與調查是自願的。"},{"en":"The company offered voluntary redundancy packages.","zh-TW":"公司提供了自願離職方案。"}]', '{"adjective":"voluntary","adverb":"voluntarily","noun":"volunteer"}', NULL, 3, 3220, 482),
(3221, 'volunteer', '/ˌvɑːlənˈtɪr/', 'noun, verb', '{"zh-TW":["志工；志願者","自願做"],"en":["a person who works without pay","to offer to do something willingly"]}', NULL, 'volunteer work / volunteer for / community volunteer', '[{"en":"Many employees volunteer for community projects.","zh-TW":"許多員工自願參加社區專案。"},{"en":"She volunteered to lead the new initiative.","zh-TW":"她自願領導新的倡議。"}]', '{"noun":"volunteer","verb":"volunteer","adjective":"voluntary"}', NULL, 3, 3221, NULL),
(3222, 'voucher', '/ˈvaʊtʃər/', 'noun', '{"zh-TW":["憑證；代金券"],"en":["a document that entitles the holder to a discount or service"]}', NULL, 'gift voucher / discount voucher / redeem a voucher', '[{"en":"Customers received a $10 gift voucher.","zh-TW":"顧客獲得了一張10美元的禮品券。"},{"en":"The voucher is valid for 30 days.","zh-TW":"該優惠券有效期為30天。"}]', '{"noun":"voucher"}', NULL, 3, 3222, NULL),
(3223, 'VPN', '/viː piː ɛn/', 'noun', '{"zh-TW":["虛擬私人網路"],"en":["a secure network connection that encrypts internet traffic"]}', NULL, 'use a VPN / VPN access', '[{"en":"Employees must use a VPN when working remotely.","zh-TW":"員工遠端工作時必須使用VPN。"},{"en":"The VPN protects company data on public Wi-Fi networks.","zh-TW":"VPN在公共無線網路上保護公司數據。"}]', NULL, NULL, 1, 3223, NULL),
(3224, 'vulnerable', '/ˈvʌlnərəbl/', 'adjective', '{"zh-TW":["脆弱的；易受攻擊的"],"en":["susceptible to harm or attack"]}', NULL, 'vulnerable to / vulnerable position / economically vulnerable', '[{"en":"Small businesses are vulnerable to economic downturns.","zh-TW":"小型企業容易受經濟衰退的影響。"},{"en":"The system is vulnerable to cyber attacks.","zh-TW":"該系統容易受到網路攻擊。"}]', '{"noun":"vulnerability","adjective":"vulnerable"}', NULL, 4, 3224, NULL),
(3225, 'wage', '/weɪdʒ/', 'noun', '{"zh-TW":["工資；薪水"],"en":["a fixed regular payment for work, usually hourly"]}', NULL, 'minimum wage / wage increase / hourly wage', '[{"en":"The minimum wage was raised to $15 per hour.","zh-TW":"最低工資提高到每小時15美元。"},{"en":"Workers demanded a wage increase.","zh-TW":"工人要求加薪。"}]', '{"noun":"wage, wages"}', NULL, 1, 3225, NULL),
(3226, 'wait', 'weɪt', 'verb', '{"zh-TW":["等待；等候","服務"],"en":["to stay until something happens","to serve at table"]}', NULL, 'wait for approval/a response', '[{"en":"Please wait for confirmation.","zh-TW":"請等待確認。"}]', '{"noun":"wait, waiter","adjective":"waiting"}', NULL, 1, 3226, NULL),
(3227, 'waiter', '/ˈweɪtər/', 'noun', '{"zh-TW":["服務生；侍者"],"en":["a person who serves food in a restaurant"]}', NULL, 'ask the waiter / experienced waiter', '[{"en":"The waiter was attentive and friendly throughout the meal.","zh-TW":"服務生在整個用餐過程中都很周到友善。"},{"en":"Please ask the waiter for today''s soup of the day.","zh-TW":"請詢問服務生今日例湯。"}]', '{"noun":"waitress","verb":"wait"}', NULL, 2, 3227, NULL),
(3228, 'waive', '/weɪv/', 'verb', '{"zh-TW":["放棄（權利）；免除"],"en":["to refrain from insisting on a right or claim"]}', NULL, 'waive a fee / waive the right / waive requirements', '[{"en":"The bank waived the processing fee.","zh-TW":"銀行免除了手續費。"},{"en":"She waived her right to appeal.","zh-TW":"她放棄了上訴權。"}]', '{"noun":"waiver","verb":"waive"}', NULL, 2, 3228, NULL),
(3229, 'waiver', '/ˈweɪvər/', 'noun', '{"zh-TW":["棄權；豁免聲明"],"en":["a voluntary relinquishment of a right or claim"]}', NULL, 'sign a waiver / liability waiver', '[{"en":"Participants must sign a liability waiver before joining.","zh-TW":"參與者在加入前必須簽署責任豁免聲明。"},{"en":"The company issued a waiver for the late payment.","zh-TW":"公司對逾期付款發出了豁免聲明。"}]', '{"verb":"waive"}', NULL, 2, 3229, NULL),
(3230, 'walk', 'wɔːk', 'verb', '{"zh-TW":["步行；走","帶領"],"en":["to move on foot","to guide through something"]}', NULL, 'walk through a process', '[{"en":"Let me walk you through the steps.","zh-TW":"讓我帶您了解這些步驟。"}]', '{"noun":"walk, walker","adjective":"walking"}', NULL, 1, 3230, NULL),
(3231, 'want', 'wɒnt', 'verb', '{"zh-TW":["【主要意義-動詞】想要；希望","【次要意義-名詞】缺乏；匱乏；貧困"],"en":["[primary - verb] to desire or wish for something","[secondary - noun] a lack or shortage; poverty"]}', NULL, 'for want of / in want / want for nothing', '[{"en":"The project failed for want of adequate funding.","zh-TW":"由於缺乏足夠的資金，這個專案失敗了。"},{"en":"Many families in the region live in want.","zh-TW":"該地區許多家庭生活在貧困中。"},{"en":"The plan was abandoned for want of support from upper management.","zh-TW":"由於缺乏高層管理的支持，該計劃被放棄了。"}]', '{"adjective":"wanting"}', '名詞 want 意為「缺乏/匱乏」，片語 for want of = 由於缺乏……，常見於 TOEIC 閱讀正式書面語境，容易與動詞用法混淆。', 1, 3231, NULL),
(3232, 'warehouse', '/ˈwerhɑʊs/', 'noun', '{"zh-TW":["倉庫；貨倉"],"en":["a large building for storing goods"]}', NULL, 'warehouse management / distribution warehouse / warehouse space', '[{"en":"The new warehouse doubles our storage capacity.","zh-TW":"新倉庫使我們的儲存容量翻倍。"},{"en":"Goods are shipped directly from the warehouse.","zh-TW":"貨物直接從倉庫出貨。"}]', '{"noun":"warehouse, warehousing"}', NULL, 3, 3232, 242),
(3233, 'warrant', '/ˈwɒrənt/', 'noun', '{"zh-TW":["搜索令；逮捕令","授權令；正當理由","保證；使有正當理由"],"en":["an official document allowing police action","a document authorizing action; justification","to justify; to guarantee"]}', NULL, 'search warrant / arrest warrant; warrant attention / arrest warrant / warrant further investigation', '[{"en":"Police obtained a search warrant.","zh-TW":"警方取得了搜索令。"},{"en":"There''s a warrant for his arrest.","zh-TW":"有一張對他的逮捕令。"},{"en":"The situation warrants immediate action.","zh-TW":"情況需要立即採取行動。"},{"en":"The findings warrant further investigation.","zh-TW":"這些發現值得進一步調查。"}]', '{"verb":"warrant","noun":"warrant, warranty"}', NULL, 3, 3233, NULL),
(3234, 'warranty', '/ˈwɒrənti/', 'noun', '{"zh-TW":["保固；保證書"],"en":["a written guarantee of product repair or replacement","a guarantee about the condition of a product"]}', '{"root":{"text":"warrant","meaning":"guarantee (保證)"},"suffix":{"text":"-y","meaning":"state (狀態)"},"logic":"保證的狀態，即「保固」。"}', 'under warranty / warranty period / extended warranty', '[{"en":"The laptop is still under warranty.","zh-TW":"這台筆電還在保固期內。"},{"en":"Would you like to purchase an extended warranty?","zh-TW":"你要購買延長保固嗎？"},{"en":"The product comes with a two-year warranty.","zh-TW":"該產品附有兩年保固。"},{"en":"Repairs are free if the item is still under warranty.","zh-TW":"如果商品仍在保固期內，維修免費。"}]', '{"noun":"warranty, warrant"}', NULL, 3, 3234, NULL),
(3235, 'waste', '/weɪst/', 'noun, verb', '{"zh-TW":["浪費；廢物","浪費"],"en":["unwanted material; extravagant use","to use carelessly"]}', NULL, 'waste of time / reduce waste / waste disposal', '[{"en":"The company reduced waste by 30% through recycling.","zh-TW":"公司透過回收減少了30%的廢物。"},{"en":"Don''t waste time on unnecessary meetings.","zh-TW":"不要把時間浪費在不必要的會議上。"}]', '{"noun":"waste, wastage","verb":"waste","adjective":"wasteful"}', NULL, 2, 3235, 483),
(3236, 'watch', 'wɒtʃ', 'verb', '{"zh-TW":["觀看；注意","監視"],"en":["to look at something carefully","to monitor"]}', NULL, 'watch a trend/presentation', '[{"en":"Watch for any unusual expenses.","zh-TW":"注意任何不尋常的費用。"}]', '{"noun":"watch, watcher","adjective":"watchful","adverb":"watchfully"}', NULL, 2, 3236, NULL),
(3237, 'way', 'weɪ', 'noun', '{"zh-TW":["方式；方法","路途"],"en":["a method or manner","a route or path"]}', NULL, 'find a way/on the way', '[{"en":"Is there a better way to handle this?","zh-TW":"有更好的方法來處理這個問題嗎？"}]', '{"adjective":"wayward","adverb":"anyway"}', NULL, 1, 3237, NULL),
(3238, 'wealth', '/welθ/', 'noun', '{"zh-TW":["財富；豐富"],"en":["an abundance of possessions or resources"]}', NULL, 'wealth management / wealth of experience / accumulate wealth', '[{"en":"Wealth management services cater to high-net-worth individuals.","zh-TW":"財富管理服務面向高淨值人士。"},{"en":"She brings a wealth of experience to the role.","zh-TW":"她為這個職位帶來了豐富的經驗。"}]', '{"noun":"wealth","adjective":"wealthy"}', NULL, 2, 3238, 484),
(3239, 'weather', '/ˈweðər/', 'noun', '{"zh-TW":["天氣"],"en":["the state of the atmosphere at a particular time"]}', '{"root":{"text":"weather","meaning":"wind/air (風/空氣)"},"logic":"源自古英語 weder（大氣狀態）。"}', 'weather forecast / bad weather / weather conditions', '[{"en":"What''s the weather like today?","zh-TW":"今天天氣如何？"},{"en":"Bad weather delayed our flight.","zh-TW":"惡劣天氣延誤了我們的航班。"}]', '{"verb":"weather"}', NULL, 3, 3239, NULL),
(3240, 'website', '/ˈwɛbsaɪt/', 'noun', '{"zh-TW":["網站"],"en":["a set of pages on the internet"]}', NULL, 'visit a website / website design', '[{"en":"Visit our website for more info.","zh-TW":"請訪問我們的網站了解更多資訊。"},{"en":"The website was redesigned last month.","zh-TW":"網站上個月重新設計了。"}]', NULL, NULL, 3, 3240, NULL),
(3241, 'welfare', '/ˈwelfer/', 'noun', '{"zh-TW":["福利；福祉"],"en":["the health and happiness of a person or group"]}', NULL, 'employee welfare / social welfare / welfare benefits', '[{"en":"Employee welfare is a top priority for the company.","zh-TW":"員工福利是公司的首要任務。"},{"en":"The government increased social welfare spending.","zh-TW":"政府增加了社會福利支出。"}]', '{"noun":"welfare"}', NULL, 3, 3241, 486),
(3242, 'well', '/wel/', 'verb, noun, adverb, adjective', '{"zh-TW":["【主要意義-副詞】好地；充分地","【次要意義-動詞】噴湧；湧出（情緒/液體）","【次要意義-名詞】水井；油井"],"en":["[primary - adverb] in a good or satisfactory way","[secondary - verb] to flow upward or outward like water from a spring","[secondary - noun] a hole drilled to obtain water or oil"]}', NULL, 'well up / tears welled / well of emotion / oil well', '[{"en":"Tears welled up in her eyes when she heard the news.","zh-TW":"當她聽到這個消息時，淚水湧上了她的眼眶。"},{"en":"Oil wells in the region produce over a million barrels per day.","zh-TW":"該地區的油井每天生產超過百萬桶石油。"},{"en":"A sense of pride welled up within the team after the successful launch.","zh-TW":"成功發布後，整個團隊湧現出一種自豪感。"}]', NULL, '動詞 well up 意為「（情緒）湧現；（液體）湧出」，名詞 well = 「水井/油井」，這兩種次要用法常見於 TOEIC 閱讀的能源或情感描述語境。', 1, 3242, NULL),
(3243, 'well-established', 'wɛl ɪˈstæblɪʃt', 'adjective', '{"zh-TW":["成熟的；成立已久的","信譽好的"],"en":["having been in existence for long","having a good reputation"]}', NULL, 'well-established company/well-established brand', '[{"en":"We are a well-established company in Taiwan.","zh-TW":"我們是台灣一家成立已久的公司。"}]', NULL, NULL, 5, 3243, NULL),
(3244, 'whereas', '/werˈæz/', 'conjunction', '{"zh-TW":["然而；反之"],"en":["in contrast to the fact that"]}', NULL, 'whereas in fact / whereas previously', '[{"en":"Sales increased in Asia, whereas they declined in Europe.","zh-TW":"銷售在亞洲增長，而在歐洲則下降。"},{"en":"The old system was manual, whereas the new one is automated.","zh-TW":"舊系統是手動的，而新系統是自動化的。"}]', NULL, NULL, 3, 3244, NULL),
(3245, 'whistleblower', '/ˈwɪslˌbloʊər/', 'noun', '{"zh-TW":["吹哨人；舉報人"],"en":["a person who reports illegal or unethical activity within an organization"]}', NULL, 'protect whistleblowers / whistleblower policy / whistleblower complaint', '[{"en":"The whistleblower exposed the company''s fraudulent accounting.","zh-TW":"吹哨人揭露了公司的欺詐性會計行為。"},{"en":"Whistleblower protections are essential for corporate accountability.","zh-TW":"吹哨人保護對公司問責至關重要。"}]', '{"verb":"blow the whistle"}', NULL, 5, 3245, NULL),
(3246, 'white-collar', '/waɪt ˈkɒlər/', 'adjective', '{"zh-TW":["白領的；辦公室工作的"],"en":["relating to professional, managerial, or administrative work in an office"]}', NULL, 'white-collar worker / white-collar crime / white-collar profession', '[{"en":"The company employs mostly white-collar workers in its headquarters.","zh-TW":"公司總部主要聘用白領工作人員。"},{"en":"White-collar crime such as fraud has increased with digital transactions.","zh-TW":"隨著數位交易的發展，詐欺等白領犯罪有所增加。"}]', '{"opposite":"blue-collar"}', NULL, 4, 3246, NULL),
(3247, 'whiteboard', '/ˈwaɪtbɔːrd/', 'noun', '{"zh-TW":["白板"],"en":["a smooth white board used for writing in meetings"]}', NULL, 'use a whiteboard / digital whiteboard', '[{"en":"The trainer drew diagrams on the whiteboard.","zh-TW":"培訓師在白板上畫了圖表。"},{"en":"Virtual whiteboards allow remote teams to collaborate visually.","zh-TW":"虛擬白板使遠端團隊能夠進行視覺協作。"}]', NULL, NULL, 4, 3247, NULL),
(3248, 'whole', 'hoʊl', 'adjective', '{"zh-TW":["整體的；全部的","完整的"],"en":["complete, not divided","all of something"]}', NULL, 'whole team/whole process', '[{"en":"The whole team contributed to the success.","zh-TW":"整個團隊為成功做出了貢獻。"}]', '{"noun":"whole","adverb":"wholly"}', NULL, 2, 3248, NULL),
(3249, 'wholesale', '/ˈhoʊlseɪl/', 'noun', '{"zh-TW":["批發","批發的"],"en":["the selling of goods in large quantities at low prices","the selling of goods in large quantities","on a large scale"]}', '{"root":{"text":"whole","meaning":"whole (整體)"},"suffix":{"text":"sale","meaning":"sale (銷售)"},"logic":"整批銷售，即「批發」。"}', 'wholesale price / wholesale market; wholesale price / wholesale market / wholesale distributor', '[{"en":"They buy wholesale and sell retail.","zh-TW":"他們批發購入，零售賣出。"},{"en":"The wholesale price is much lower.","zh-TW":"批發價便宜很多。"},{"en":"We buy materials at wholesale prices.","zh-TW":"我們以批發價購買材料。"},{"en":"The wholesale market opens at 5 AM.","zh-TW":"批發市場凌晨5點開門。"}]', '{"noun":"wholesaler","adjective":"wholesale"}', NULL, 3, 3249, NULL);